@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container py-5">
    <div class="text-center mb-5">
        <h1 class="display-4">Welcome to ShipmentTracker</h1>
        <p class="lead text-muted">Your trusted partner in global logistics. Track your shipments in real time, anywhere in the world.</p>
    </div>

    <div class="row justify-content-center mb-4">
        <div class="col-md-6">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Track Your Shipment</h5>
                    <p class="card-text">Enter your tracking number below to see the latest status of your shipment.</p>
                    <div class="input-group">
                        <input type="text" class="form-control" placeholder="e.g. ST-100001" @bind="trackingNumber" @bind:event="oninput"
                               @onkeydown="HandleKeyDown" />
                        <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                            Track
                        </button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <div class="text-center">
        <p>Are you a dispatcher? <a href="/dashboard" class="btn btn-outline-secondary btn-sm">Go to Dashboard</a></p>
    </div>
</div>

@code {
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private string trackingNumber = string.Empty;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

@page "/dashboard"

@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

@attribute [Authorize]

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1 class="mb-4">Dispatcher Dashboard</h1>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @bind="selectedStatus">
                <option value="">All</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Search</label>
            <input type="text" class="form-control" placeholder="Tracking # or destination..." @bind="searchQuery" @bind:event="oninput" />
        </div>
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
                    <th>Update Status</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><a href="/track/@shipment.TrackingNumber">@shipment.TrackingNumber</a></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm" value="@shipment.Status"
                                    @onchange="e => UpdateStatus(shipment.Id, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter criteria.</div>
    }
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger mt-3">@errorMessage</div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment>? shipments;
    private string selectedStatus = "";
    private string searchQuery = "";
    private string? errorMessage;

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            if (shipments is null) return Enumerable.Empty<Shipment>();

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrEmpty(selectedStatus) && Enum.TryParse<ShipmentStatus>(selectedStatus, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            if (!string.IsNullOrWhiteSpace(searchQuery))
            {
                var q = searchQuery.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(q, StringComparison.OrdinalIgnoreCase));
            }

            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (e.Value is string val && Enum.TryParse<ShipmentStatus>(val, out var newStatus))
        {
            errorMessage = null;
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            if (updated is null)
            {
                errorMessage = "Failed to update shipment status.";
            }
            else
            {
                shipments = await ShipmentService.GetAllShipmentsAsync();
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track/{TrackingNumber}"

@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>Track Shipment - @TrackingNumber</PageTitle>

<h1 class="mb-4">Track Shipment</h1>

@if (loading)
{
    <p><em>Loading shipment details...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        <h4 class="alert-heading">Shipment Not Found</h4>
        <p>We couldn't find a shipment with tracking number <strong>@TrackingNumber</strong>. Please check the tracking number and try again.</p>
        <hr />
        <a href="/" class="btn btn-outline-primary">Back to Home</a>
    </div>
}
else
{
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Customer</dt>
                        <dd>@shipment.CustomerName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd>@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy 'at' HH:mm")</dd>
                        }
                    </dl>
                </div>
            </div>
        </div>
    </div>

    <h4 class="mb-3">Tracking History</h4>

    @if (shipment.TrackingEvents.Any())
    {
        <div class="list-group">
            @foreach (var evt in shipment.TrackingEvents.OrderByDescending(e => e.Timestamp))
            {
                <div class="list-group-item">
                    <div class="d-flex justify-content-between align-items-start">
                        <div>
                            <h6 class="mb-1">@evt.Description</h6>
                            <p class="mb-1 text-muted">@evt.Location</p>
                        </div>
                        <div class="text-end">
                            <span class="badge @GetStatusBadgeClass(evt.Status)">@evt.Status</span>
                            <br />
                            <small class="text-muted">@evt.Timestamp.ToString("MMM dd, yyyy HH:mm")</small>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <p class="text-muted">No tracking events available yet.</p>
    }
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = string.Empty;
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private Shipment? shipment;
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
